exports.handler = async (event, context) => {
  const safeEvent = JSON.parse(JSON.stringify(event));
  for (const key of Object.keys(safeEvent.headers || {})) {
    if (['authorization', 'x-amz-security-token'].includes(key.toLowerCase())) safeEvent.headers[key] = '[REDACTED]';
  }
  return {statusCode: 200, headers: {'content-type': 'application/json'}, body: JSON.stringify({
    ownedProbe: true, revision: process.env.REVISION, version: context.functionVersion,
    invokedFunctionArn: context.invokedFunctionArn, event: safeEvent
  })};
};
